const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.title = "Generative AI's Act Two: From Technology Hammer to Real Value";
pres.author = "Sequoia Capital";

// Color palette - Midnight Executive style
const COLORS = {
  navy: "1E2761",
  darkNavy: "0F1B2E",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  lightGray: "F1F5F9",
  slate: "64748B",
  accent: "3B82F6",
  success: "10B981",
  danger: "EF4444",
  amber: "F59E0B"
};

// ============================================
// SLIDE 1: Title Slide
// ============================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkNavy };

// Accent line at top
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.accent }
});

// Main title
slide1.addText("Generative AI's Act Two", {
  x: 0.75, y: 1.6, w: 8.5, h: 0.9,
  fontSize: 44, fontFace: "Arial", bold: true,
  color: COLORS.white, margin: 0
});

slide1.addText("From Technology Hammer to Real Value", {
  x: 0.75, y: 2.45, w: 8.5, h: 0.6,
  fontSize: 28, fontFace: "Arial",
  color: COLORS.iceBlue, margin: 0
});

// Attribution
slide1.addText("Sequoia Capital", {
  x: 0.75, y: 3.5, w: 4, h: 0.4,
  fontSize: 16, fontFace: "Arial", bold: true,
  color: COLORS.accent, margin: 0
});

slide1.addText("Sonya Huang, Pat Grady | September 2023", {
  x: 0.75, y: 3.9, w: 4, h: 0.35,
  fontSize: 12, fontFace: "Arial",
  color: COLORS.slate, margin: 0
});

// Decorative shape - vertical bar
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 9.0, y: 1.2, w: 0.6, h: 3.2,
  fill: { color: COLORS.accent, transparency: 30 }
});

// ============================================
// SLIDE 2: Six Decades of Convergence
// ============================================
let slide2 = pres.addSlide();
slide2.background = { color: COLORS.white };

slide2.addText("Six Decades of Technological Progress Converged to Enable Generative AI", {
  x: 0.75, y: 0.4, w: 8.5, h: 0.7,
  fontSize: 26, fontFace: "Arial", bold: true,
  color: COLORS.darkNavy, margin: 0
});

// Timeline items - three columns
const timelineItems = [
  { decades: "6 Decades", title: "Moore's Law", desc: "Compute horsepower to process exaflops of data", color: COLORS.accent },
  { decades: "4 Decades", title: "The Internet", desc: "Trillions of tokens of training data (accelerated by COVID)", color: COLORS.success },
  { decades: "2 Decades", title: "Mobile & Cloud", desc: "Supercomputer in every human's palm", color: COLORS.amber }
];

timelineItems.forEach((item, i) => {
  const x = 0.75 + i * 3.1;

  // Card background
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.4, w: 2.9, h: 2.8,
    fill: { color: COLORS.lightGray }
  });

  // Colored top accent
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.4, w: 2.9, h: 0.1,
    fill: { color: item.color }
  });

  // Decades badge
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: x + 0.2, y: 1.7, w: 1.3, h: 0.45,
    fill: { color: item.color }
  });
  slide2.addText(item.decades, {
    x: x + 0.2, y: 1.7, w: 1.3, h: 0.45,
    fontSize: 11, fontFace: "Arial", bold: true,
    color: COLORS.white, align: "center", valign: "middle", margin: 0
  });

  // Title
  slide2.addText(item.title, {
    x: x + 0.2, y: 2.3, w: 2.5, h: 0.5,
    fontSize: 18, fontFace: "Arial", bold: true,
    color: COLORS.darkNavy, margin: 0
  });

  // Description
  slide2.addText(item.desc, {
    x: x + 0.2, y: 2.8, w: 2.5, h: 1.0,
    fontSize: 13, fontFace: "Arial",
    color: COLORS.slate, margin: 0
  });
});

// Bottom note
slide2.addText("ChatGPT's launch ignited a Cambrian explosion of innovation not seen since the early internet.", {
  x: 0.75, y: 4.6, w: 8.5, h: 0.4,
  fontSize: 12, fontFace: "Arial", italic: true,
  color: COLORS.slate, margin: 0
});

// ============================================
// SLIDE 3: GenAI Outpaces SaaS
// ============================================
let slide3 = pres.addSlide();
slide3.background = { color: COLORS.white };

slide3.addText("GenAI Startups Surpassed $1B Revenue Faster Than SaaS Ever Did", {
  x: 0.75, y: 0.4, w: 8.5, h: 0.7,
  fontSize: 26, fontFace: "Arial", bold: true,
  color: COLORS.darkNavy, margin: 0
});

// Big stat callout
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.75, y: 1.3, w: 4.2, h: 2.0,
  fill: { color: COLORS.darkNavy }
});

slide3.addText(">$1B", {
  x: 0.75, y: 1.4, w: 4.2, h: 1.1,
  fontSize: 60, fontFace: "Arial", bold: true,
  color: COLORS.white, align: "center", valign: "middle", margin: 0
});

slide3.addText("Startup revenue in months, not years", {
  x: 0.75, y: 2.5, w: 4.2, h: 0.6,
  fontSize: 13, fontFace: "Arial",
  color: COLORS.iceBlue, align: "center", valign: "top", margin: 0
});

// Standout examples
const examples = [
  { name: "ChatGPT", stat: "Fastest-growing app in history", highlight: true },
  { name: "Midjourney", stat: "Hundreds of millions in revenue with 11 employees", highlight: false },
  { name: "Character.ai", stat: "2-hour average session time", highlight: false }
];

examples.forEach((ex, i) => {
  const y = 1.3 + i * 0.7;

  if (ex.highlight) {
    slide3.addShape(pres.shapes.RECTANGLE, {
      x: 5.2, y: y, w: 0.08, h: 0.55,
      fill: { color: COLORS.accent }
    });
  }

  slide3.addText(ex.name, {
    x: 5.45, y: y, w: 3.8, h: 0.35,
    fontSize: 16, fontFace: "Arial", bold: true,
    color: COLORS.darkNavy, margin: 0
  });
  slide3.addText(ex.stat, {
    x: 5.45, y: y + 0.3, w: 3.8, h: 0.3,
    fontSize: 12, fontFace: "Arial",
    color: COLORS.slate, margin: 0
  });
});

// Bottom context
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.75, y: 3.6, w: 8.5, h: 1.5,
  fill: { color: COLORS.lightGray }
});

slide3.addText("However, these successes don't change the reality that many AI companies lack product-market fit or sustainable competitive advantage.", {
  x: 0.95, y: 3.8, w: 8.1, h: 1.1,
  fontSize: 14, fontFace: "Arial", italic: true,
  color: COLORS.darkNavy, margin: 0
});

// ============================================
// SLIDE 4: Retention Gap - Bar Chart
// ============================================
let slide4 = pres.addSlide();
slide4.background = { color: COLORS.white };

slide4.addText("AI-First Apps Show 14% Median Retention vs. 51% for Incumbents", {
  x: 0.75, y: 0.35, w: 8.5, h: 0.6,
  fontSize: 24, fontFace: "Arial", bold: true,
  color: COLORS.darkNavy, margin: 0
});

// Incumbent data
const incumbentData = [
  { name: "WhatsApp", retention: 85 },
  { name: "Instagram", retention: 64 },
  { name: "YouTube", retention: 64 },
  { name: "TikTok", retention: 60 },
  { name: "Snapchat", retention: 51 },
  { name: "Roblox", retention: 41 },
  { name: "Tinder", retention: 34 },
  { name: "Candy Crush", retention: 32 },
  { name: "Duolingo", retention: 30 }
];

// AI-First data
const aiFirstData = [
  { name: "Character.ai", retention: 41 },
  { name: "Runway", retention: 27 },
  { name: "Remini", retention: 14 },
  { name: "ChatGPT", retention: 14 },
  { name: "Lensa", retention: 12 }
];

// Chart dimensions
const chartX = 0.75;
const chartY = 1.1;
const chartW = 5.5;
const chartH = 3.8;

// Calculate bar positions
const incumbentMaxVal = 85;
const aiFirstMaxVal = 41;
const barGroupWidth = 0.35;

// Draw incumbent bars
incumbentData.forEach((app, i) => {
  const barHeight = (app.retention / incumbentMaxVal) * (chartH * 0.6);
  const x = chartX + i * 0.55;
  const y = chartY + chartH - 0.4 - barHeight;

  slide4.addShape(pres.shapes.RECTANGLE, {
    x: x, y: y, w: barGroupWidth, h: barHeight,
    fill: { color: COLORS.darkNavy }
  });

  // Label at bottom
  slide4.addText(app.name, {
    x: x - 0.1, y: chartY + chartH - 0.25, w: 0.6, h: 0.3,
    fontSize: 7, fontFace: "Arial",
    color: COLORS.slate, align: "center", margin: 0, rotate: 270
  });

  // Value at top
  slide4.addText(app.retention + "%", {
    x: x - 0.05, y: y - 0.2, w: 0.5, h: 0.2,
    fontSize: 8, fontFace: "Arial", bold: true,
    color: COLORS.darkNavy, align: "center", margin: 0
  });
});

// Draw AI-First bars (grouped)
const aiBarWidth = 0.25;
const aiBarGap = 0.03;
aiFirstData.forEach((app, i) => {
  const barHeight = (app.retention / incumbentMaxVal) * (chartH * 0.6);
  const x = chartX + 4.7 + i * (aiBarWidth + aiBarGap + 0.08);
  const y = chartY + chartH - 0.4 - barHeight;

  slide4.addShape(pres.shapes.RECTANGLE, {
    x: x, y: y, w: aiBarWidth, h: barHeight,
    fill: { color: COLORS.accent }
