  color: COLORS.darkNavy, margin: 0
});

slide7.addText("From technology hammer to actual value delivery. The increasingly multi-modal nature of applications means the old modality-based categorization no longer reflects how products are built or how customers think about them. Companies like Harvey, Glean, Character, and Ava exemplify use-case-driven development where AI capabilities serve human problems, not the other way around.", {
  x: 1.0, y: 4.05, w: 8.0, h: 1.0,
  fontSize: 11, fontFace: "Arial",
  color: COLORS.slate, margin: 0
});

// ============================================
// SLIDE 8: Key Takeaways
// ============================================
let slide8 = pres.addSlide();
slide8.background = { color: COLORS.darkNavy };

// Accent line
slide8.addShape(pres.shapes.RECTANGLE, {
