  fill: { color: COLORS.accent }
});

slide8.addText("Key Takeaways: What Separates Winners in Act Two", {
  x: 0.75, y: 0.5, w: 8.5, h: 0.7,
  fontSize: 26, fontFace: "Arial", bold: true,
  color: COLORS.white, margin: 0
});

const takeaways = [
  { num: "1", text: "Retention is the critical challenge — AI-first apps at 14% median vs. 51% for incumbents" },
  { num: "2", text: "Foundation models should be a component, not the whole product" },
